  VALUES 
    (612::BIGINT, 'Es un buen profesor para iniciar materias de la carrera.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa']::TEXT[], '2025-09-06T00:00:00+00:00'::TIMESTAMPTZ, '873eec859f45fe4af1459e857d9a5046f00a9ec47077a33d5c7f74707cae5691'::TEXT, ARRAY[1709]::BIGINT[]),
    (612::BIGINT, 'Para modelado siento que es mejor con Federico, ya que luego se lleva tridi, y eso siempre lo da Fede, asi que usted ya va acostumbrado a trabajar con la modalidad de el.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'afcf670d66cc2cc38c7375edd2f04b55a884d468588d68051c95313779ec35db'::TEXT, ARRAY[1851]::BIGINT[]),
    (612::BIGINT, 'El profe es súper bueno, es increíble lo claro que es todo, especialmente para primeros ingresos es súper amigable el curso y motiva mucho. las instrucciones y rúbricas de todas sus tareas son muy fáciles de cumplir, sólo hay que seguir lo que dice al pie'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'dccd1317bb8bd384c0b602bce3faf591246b997c4598b829e39f018268e678ed'::TEXT, ARRAY[1709]::BIGINT[]),
    (612::BIGINT, 'Realmente buen profe, sus tareas son interesantes, hay que dedicarles tiempo, más al proyecto, muy buena persona y hace la clase amena.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, '1189563aa5d11c2ec244cd025f820a08ba67d3b4e71ae159716f4b540547854d'::TEXT, ARRAY[1709]::BIGINT[]),
    (612::BIGINT, 'Las clases son muy dinámicas, para las tareas es de dedicarle su rato y de ser posible consultarle al profe cualquier ambiguedad, fuera de eso genial.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2024-06-16T00:00:00+00:00'::TIMESTAMPTZ, '87cfd69bc6098418241dff091fa867d5b641ccb5dfd733bbb011737662db65f2'::TEXT, ARRAY[1845]::BIGINT[]),
    (612::BIGINT, 'El profe es muy buena gente, solo que a veces puede llegar a ser confusa su explicación de la tarea y le toca a uno solo ver cómo logra hacerla porque aunque uno vaya a consulta, no se explica de la mejor manera para saber qué es lo que hay que hacer específicamente'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2024-02-02T00:00:00+00:00'::TIMESTAMPTZ, '8f9570e304744ad10155e75852569ccee050144f5357554300809fceeb0a96c7'::TEXT, ARRAY[1845, 1709]::BIGINT[]),
    (612::BIGINT, 'Metodos:???? Analisis:????'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '8bd45cdf8e356498f0b63d233a82fa1ee45dbf903402e7055456741a6c810bcc'::TEXT, ARRAY[1709, 1845]::BIGINT[]),
    (612::BIGINT, 'Las explicaciones pueden ser ambiguas y sus clases se pueden volver algo monótonas pero en general se aprende. El profe es buena gente'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '2a6517b61feb309602b8ad5737063081dbad600f935af76a93bb213aeb4ff1d7'::TEXT, ARRAY[1709]::BIGINT[]),
    (612::BIGINT, 'Es un buen profe, pero las indicaciones en los trabajos son ambiguas y califica duro.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '39027ad3d2604b39623b4187f8a1406a7752aca5b8caa7802001da16feba7415'::TEXT, ARRAY[1845]::BIGINT[]),
    (612::BIGINT, 'Métodos requiere bastante tiempo. En lo personal, nunca fui a consulta y siempre quedaron las cosas muy claras con él, además de que intentaba hacer las clases diferentes y dinámicas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'da872aca51acd8728fdc917f544c7f9111867eba85a92fe87218016c54ec0d47'::TEXT, ARRAY[1709]::BIGINT[]),
    (612::BIGINT, 'Cuando explica, uno parece entender todo, pero se complica cuando uno empieza a trabajar. A pesar de esto, la clase es llevadera. El profe va y hace lo que tiene que hacer con simpleza. Estas dos materias son duras de por sí, así que póngale con quien sea que las lleve.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-06-07T00:00:00+00:00'::TIMESTAMPTZ, '16061d5c76f131b70dc7fb192d98da802a9c81c8175b7a6c24f9884266cfce30'::TEXT, ARRAY[1845, 1709]::BIGINT[]),
    (612::BIGINT, 'Hay que ponerle bastante (sobretodo en análisis) porque las evaluaciones pueden ser rudas (nada de nervios si les va mal al principio, es normal). Aprovechen las consultas y todo saldrá bien. Muy dinámico y llevador llevar ambos cursos con él.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'be9c337acd415901f6c0fc0214b16706e132643a2ec8b2354664636d0cf7f308'::TEXT, ARRAY[1845, 1709]::BIGINT[]),
    (612::BIGINT, 'Sus clases son excelentes, deja todo muy claro y sieeeempre está dispuesto a explicarte o ayudarte. Me encantaron sus clases, volvería a tomar clases con él sin dudarlo. Su evaluación es muy clara'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-12T00:00:00+00:00'::TIMESTAMPTZ, '68daa65ecbe6531dbb1b6826df42a88271a6120b4e9f27fd33644e3e29e6c37d'::TEXT, ARRAY[1709]::BIGINT[]),
    (612::BIGINT, 'Es un excelente profe. Se nota su interés por hacer las cosas bien y que uno aprenda. Las clases son muy dinámicas y agradables. Es muy comprensivo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '816e897f3e6d29a4555fd7ec2451266ba5a91d8c365a0533481ebfb9933b06f9'::TEXT, ARRAY[1709]::BIGINT[]),
    (612::BIGINT, 'Súper buen profe, las clases son muy dinámicas y las tareas son relativamente divertidas y entretenidas. Lo súper recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-05-11T00:00:00+00:00'::TIMESTAMPTZ, '4c9ec05ec99673e220e8c08cdceb2a3d3d38146cf87b8850bd9cedf9df487d33'::TEXT, ARRAY[1709]::BIGINT[]),
    (612::BIGINT, 'Mala retroalimentación y tiene favoritísmos'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-03-02T00:00:00+00:00'::TIMESTAMPTZ, '6298fa28dc8512b10f80e9e184cc4528f77925004de1f14853969188a2188d1f'::TEXT, ARRAY[1845]::BIGINT[]),
    (612::BIGINT, 'El mejor profe que pueda existir para un curso con proyecciones de automatización e ingeniería. Las entregas valen entre el 10 y el 25 % de la nota cada una por lo que realmente saca lo mejor de cada persona.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, '9177a363c9e91d86307af0c9db99a8a74415a250aca51cba43431c711ef55d17'::TEXT, ARRAY[1875]::BIGINT[]),
    (612::BIGINT, 'El mejor profe, explica muy bien y sus clases son muy entretenidas. Uno aprende de verdad y no se aburre en clases. Lo recomiendo mucho!'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '9a441c7d8b4a46f5c6d331f318ca2f15349c60ed1201ad5c5f2c4d07d04a561a'::TEXT, ARRAY[1709]::BIGINT[]),
    (612::BIGINT, 'Excelente profe y persona. Le gusta ayudar y siempre está a disposición de los estudiantes. También es muy comprensivo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '8c9f542a304b1eb5d3b75fcb6126ba04613c877f04b8d14ee1f897746858a3af'::TEXT, ARRAY[1851]::BIGINT[]),
    (612::BIGINT, 'La materia es super aburrida pero LuisCa es muy buen profesor'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2019-06-29T00:00:00+00:00'::TIMESTAMPTZ, '7704e48638779c424b30b3e6a5c9adc4f1b9c4aa0bb9ff9438895568b14bfd5e'::TEXT, ARRAY[1856]::BIGINT[]),
