    (612::BIGINT, 'Actividades divertidas. Muy organizado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'd8638bf6bbecd09c15fa892cce5baaaaec4736da83ed4af06b387f60110711aa'::TEXT, ARRAY[1845]::BIGINT[]),
    (612::BIGINT, 'Buen profe, lo ayuda mucho a uno si hay dudas. PD: importante ir a consulta'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, '3ecd4b91f558cbfb7340747ef93576168dc99e493a23ac5cdae9ff08809ed3b6'::TEXT, ARRAY[1851]::BIGINT[]),
    (612::BIGINT, 'muy buen profe, le gusta lo que enseña y se nota que lo apasiona. ayuda mucho, pero es necesario ir a consulta para entender algunas cosas. da muy bien las clases y es muy claro.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, '4a95088ffd8bb0d087dc2881a125c79d9aa564f9807f6b09f78cca50c4d7254a'::TEXT, ARRAY[1851]::BIGINT[]),
    (612::BIGINT, 'Es buen profe. En las clases solo lee las diapositivas, es cierto, pero las actividades que hacen en clase son demasiado divertidas y si se aprende.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'a8a2239ad14ae5ae901754a10747612eed526e8d32b66c779cb919cdf52cde37'::TEXT, ARRAY[1845]::BIGINT[]),
    (612::BIGINT, 'Como persona es excelente, le gusta vacilar, pero en clases solo lee las presentaciones y es muy estricto con respecto a la hora de las entregas.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, '0c8399d2ad0e7228ac080593826c05eead7693e5998ea71ca00cb8a26a8696a9'::TEXT, ARRAY[1709]::BIGINT[]),
    (612::BIGINT, 'Las instrucciones son claras, no es necesario ir a consulta. Las clases y las actividades son divertidas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-08-18T00:00:00+00:00'::TIMESTAMPTZ, '47a26d95b2be2a92d7dfa6f23053cf3d38151b25c4b6e5dbfd8187fd7f7d6076'::TEXT, ARRAY[1845]::BIGINT[]),
    (612::BIGINT, 'Califica muy suave, no se necesita ir a consulta para pasar bien.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '85e6c7802178cf79015272896e0ebb571c8b80f7d8fc0939cd485a218475222a'::TEXT, ARRAY[1845]::BIGINT[]),
    (612::BIGINT, 'Hay que ponerle en el curso, pero el profe es una teja!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2018-04-06T00:00:00+00:00'::TIMESTAMPTZ, 'daedf06008462d0944495f3e94a7e45c93dd12b3eeb510437cbeece540e18495'::TEXT, ARRAY[1845]::BIGINT[]),
    (612::BIGINT, 'Es uno de los mejores profes de diseño industrial y aun más en ergonomía, le pone mucho entusiasmo, da ejemplos útiles que dan perspectiva al diseño en el mundo real.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2018-01-18T00:00:00+00:00'::TIMESTAMPTZ, '838d5f2d7d5384d0230b911abd52ee6affffcab3e0d6d692ac4a361383826d03'::TEXT, ARRAY[1856]::BIGINT[]),
    (612::BIGINT, 'Si tiene la oportunidad de matricular con él, dele de una. Es de los mejores profes de la escuela, lo hace a uno interesarse en lo que aprende. Es una teja de persona, SÚPER recomendado!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-17T00:00:00+00:00'::TIMESTAMPTZ, '128d3cae85ffb52619cda41ebd03ec5f91426a08b9d39bab647c34c8c7092a24'::TEXT, ARRAY[1845, 1851]::BIGINT[]),
