    (612::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'd2ee5a1cc362f94e0d2658878268e0fe78b026cc502f5867234e74c3fe750698'::TEXT, ARRAY[1845]::BIGINT[]),
    (612::BIGINT, 'El curso es pesado para valer dos créditos así que... ¡Prepárase! Luis Ca en este curso está en su salsa, así que los bretes que le va a dejar son bastante interesantes pero se aprende un vergazo, así que atento/a. Excelente profe.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2017-06-12T00:00:00+00:00'::TIMESTAMPTZ, '63853efa9ffde0cdfaba0e102ea6913e2d45294f5357bff27cda4efb7da31d61'::TEXT, ARRAY[1856]::BIGINT[]),
    (612::BIGINT, '¡Luis Ca es Luis Ca! Definitivamente, uno de los mejores profesores de la Escuela. Entiende el significado de la palabra pedagogía (que parece no ser claro para muchos profesores en Diseño). Las clases son muy entretenidas y va a hacer que ame cada curso que lleve con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'e982c16de1aabc3963d0c3c9101afbe68e19bf1635e8f2f5f1906dfb66e84f69'::TEXT, ARRAY[1931, 1851]::BIGINT[]),
    (612::BIGINT, 'luisca crack'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '42f96336ca85289abdc75e456f77f146e67984f5daa1bcf0d67d9956c7a559dc'::TEXT, ARRAY[1851, 1709]::BIGINT[]),
    (612::BIGINT, 'Es muy claro a la hora de explicar! y es muy organizado y puntual con la entrega de trabajos. Super pura vida pero obvio hay que ponerle bonito en las clases y los trabajos, pero lo mejor de todo es que siempre logra que a todos sus estudiantes les encante lo que hacen. Es muy ingenioso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2017-01-30T00:00:00+00:00'::TIMESTAMPTZ, '5a8277c81f327e06b1d909b92d4980bea5014b670af40750a568d8d86a085a32'::TEXT, ARRAY[1132]::BIGINT[]),
    (612::BIGINT, 'El trabajo en clase y proyectos tienen un buen nivel de complejidad pero la clase es bastante divertida y amena; por lo que va a aprender mucho. Califica normal y siempre esta dispuesto a ayudar! EXC profe'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2016-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'bc014b11feb92b6dd98d593b18360312a96e9321efd817bd38a1dd5fcd4d03bb'::TEXT, ARRAY[1931]::BIGINT[]),
    (612::BIGINT, 'Clase favorita de la carrera hasta el momento. MUY buen profesor. Clases dinámicas y trabajos muy interesantes. Super recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'a9430e09b58e910729703000a7e6fa87ccf6e0aed6620b5ab8dc1c1e03061191'::TEXT, ARRAY[1851]::BIGINT[]),
    (612::BIGINT, 'Rubricas muy claras y útiles. Explicaciones claras y sencillas. Una consulta muy agradable y un profesor con el que se puede vacilar. Ninguna queja con respecto a él ni a este curso. Matrículelo con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, '6aad0829d201da8b50008959e874e9b1046212c534e5d8ecfd6b6c490cb20639'::TEXT, ARRAY[1709]::BIGINT[]),
    (612::BIGINT, 'Es buena persona y es paciente en consulta, la clase se presta para ir a consulta por lo que le aconsejo que vaya; califica con base en rúbrica por lo que él no es estricto, simplemente califica según rubrica. Puede mejorar pero el hecho de que elabore una clase amena lo vuelve un buen profesor.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '35ee17e9c7bb9a5a8d99d792ef6d940cb031efb11d69cdd3e83823d96bdace6a'::TEXT, ARRAY[1709]::BIGINT[]),
    (612::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'cf5ffc0e3cb8a62f27d718470c46da11ab45b51e1d21dc8de0ee38ac837e7b89'::TEXT, ARRAY[1856]::BIGINT[]),
    (612::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '9475e1513825a3c38d2d48d5728e6fcbdd11fee236aafbcd56c0892e7f93e133'::TEXT, ARRAY[1931, 1856]::BIGINT[]),
    (612::BIGINT, 'Será muy estricto en su método de enseñanza, pero es congruente con lo que hace, ordenado y se aprende muchísimo. Recomendado.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'fe67e9c50feae62110137b05f69c1e6240b8b180692333f592757f51e1c21814'::TEXT, ARRAY[1931, 1856]::BIGINT[]),
    (612::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'eb104df055fc8710d5c0fa3ec6d13b33a700d54c6e209b786eed5c4948389a5c'::TEXT, ARRAY[1856]::BIGINT[]),
    (612::BIGINT, 'Profesor que solo lee las presentaciones y cambia palabras para decir que explica, no deja clara la materia y es muy exigente para calificar lo que lo hace cero congruente con su metodo de enseñanza (si es que tiene alguno)'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '8c4cadbe52aea9f28e8df992c5d5bccd99a96621fec675e4addb06d44bdea629'::TEXT, ARRAY[1709]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
